// Sandbox is one of sandboxes: A Linux machine with its own kernel, made in milliseconds, paused with its memory kept when idle and resumed where it was. Its life: running, then idle, then paused, until you delete it. A paused sandbox is kept with its memory and disk until it is deleted: it has no time limit, no retention period and no expiry, and nothing deletes it for its age. Every 30 days a sandbox stays paused with nothing changing it, a `sandbox.still_paused` event is written for its organization.
type Sandbox struct {
	c *Sandboxes
	// Info is what it was when last read.
	Info *SandboxInfo
	Files *SandboxFiles
	Processes *SandboxProcesses
	Network *SandboxNetworkCalls
}

func newSandbox(c *Sandboxes, info *SandboxInfo) *Sandbox {
	return &Sandbox{c: c, Info: info, Files: &SandboxFiles{c: c, id: info.ID}, Processes: &SandboxProcesses{c: c, id: info.ID}, Network: &SandboxNetworkCalls{c: c, id: info.ID}}
}

// ID is its id.
func (s *Sandbox) ID() string { return s.Info.ID }

// Refresh Returns a sandbox.
func (s *Sandbox) Refresh(ctx context.Context, q *SandboxGetQuery, opts *RequestOptions) error {
	var qb SandboxGetQuery
	if q != nil {
		qb = *q
	}
	got, err := s.c.Get(ctx, s.Info.ID, qb, opts)
	if err != nil {
		return err
	}
	s.Info = got.Info
	return nil
}

// Delete Deletes a sandbox, its memory and its disk.
func (s *Sandbox) Delete(ctx context.Context, opts *RequestOptions) (*SandboxInfo, error) {
	return s.c.Delete(ctx, s.Info.ID, opts)
}

// Pause Pauses a sandbox with its memory and disk kept. A call to it resumes it.
func (s *Sandbox) Pause(ctx context.Context, opts *RequestOptions) error {
	got, err := s.c.Pause(ctx, s.Info.ID, opts)
	if err != nil {
		return err
	}
	s.Info = got
	return nil
}

// Resume Resumes a paused sandbox where it was, its memory and processes as they were.
func (s *Sandbox) Resume(ctx context.Context, opts *RequestOptions) error {
	got, err := s.c.Resume(ctx, s.Info.ID, opts)
	if err != nil {
		return err
	}
	s.Info = got
	return nil
}

// Exec Runs a command as a process and returns it once it ended, with its output; with wait false, at once, while it runs. A paused sandbox is resumed first. Asked again with the same Idempotency-Key, it runs nothing more: it returns the first run's process, waiting for its end while it runs.
func (s *Sandbox) Exec(ctx context.Context, cmd string, in *ExecRequest, opts *RequestOptions) (*Process, error) {
	var b ExecRequest
	if in != nil {
		b = *in
	}
	if cmd != "" {
		b.Cmd = cmd
	}
	return s.c.Exec(ctx, s.Info.ID, b, opts)
}

// Metrics Returns a sandbox's CPU, memory, disks and pressure, as its host reads them from the sandbox's own cgroup over a fifth of a second: never a call into the sandbox, so it does not wake a paused one nor keep one from its idle pause. One that is not running has no reading.
func (s *Sandbox) Metrics(ctx context.Context, q *SandboxMetricsQuery, opts *RequestOptions) (*SandboxMetrics, error) {
	var qb SandboxMetricsQuery
	if q != nil {
		qb = *q
	}
	return s.c.Metrics(ctx, s.Info.ID, qb, opts)
}

// Fork Copies a sandbox as it is now, memory and disk, into `count` copies of its own, each running on its host. Asked again with the same Idempotency-Key, it returns the same copies.
func (s *Sandbox) Fork(ctx context.Context, in *ForkRequest, opts *RequestOptions) (*Forked, error) {
	var b ForkRequest
	if in != nil {
		b = *in
	}
	return s.c.Fork(ctx, s.Info.ID, b, opts)
}

// Snapshot Keeps a sandbox's memory and disk as they are now, a snapshot to start sandboxes from; with `image`, its disk alone as that image's next version. The sandbox runs on. Asked again with the same Idempotency-Key, it returns the same snapshot.
func (s *Sandbox) Snapshot(ctx context.Context, in *SnapshotRequest, opts *RequestOptions) (*Stored, error) {
	var b SnapshotRequest
	if in != nil {
		b = *in
	}
	return s.c.Snapshot(ctx, s.Info.ID, b, opts)
}

// Update Changes its name, labels, idle pause, maxCost, environment or sizes; each field left out stays as it is. A running one holds a changed environment before this answers (a paused one's at its wake): each process it starts after the answer has it, and its running processes keep the one they started with. Its vCPUs, memory and disk grow while it runs, its commands running on; a smaller size, or a sandbox that is not running, is refused 409 naming why, and nothing is changed. With If-Match, made only while its revision is that one, else 412.
func (s *Sandbox) Update(ctx context.Context, in *MachineUpdate, opts *RequestOptions) error {
	var b MachineUpdate
	if in != nil {
		b = *in
	}
	got, err := s.c.Update(ctx, s.Info.ID, b, opts)
	if err != nil {
		return err
	}
	s.Info = got
	return nil
}

// Screenshot Returns what a sandbox's screen shows now, as `image/png` (or `image/jpeg`): its X display `:1`, whole. Refused 409 `display_not_running` when no display runs. A paused sandbox is resumed first.
func (s *Sandbox) Screenshot(ctx context.Context, q *SandboxScreenshotQuery, opts *RequestOptions) ([]byte, error) {
	var qb SandboxScreenshotQuery
	if q != nil {
		qb = *q
	}
	return s.c.Screenshot(ctx, s.Info.ID, qb, opts)
}

// Act Moves, clicks, drags and scrolls the mouse and types on the keyboard of a sandbox's screen (its X display `:1`), each step in turn as one command, and returns where the mouse is then. It stops at the first step that fails, refused 409 `act_failed` naming it; refused 409 `display_not_running` when no display runs. A paused sandbox is resumed first.
func (s *Sandbox) Act(ctx context.Context, actions []Action, in *ActRequest, opts *RequestOptions) (*Acted, error) {
	var b ActRequest
	if in != nil {
		b = *in
	}
	b.Actions = actions
	return s.c.Act(ctx, s.Info.ID, b, opts)
}

// RunCode Runs a cell of Python in a sandbox as a notebook does, in a Jupyter kernel it keeps running for the cell's `context`: variables, imports and functions stay for the next cell. Returns what it printed, its values and displays (text, HTML, images such as charts), and its exception with its traceback. The context's kernel starts on its first cell. A cell past `timeoutSeconds` is interrupted and its context kept. Refused 409 `kernel_not_installed` when the image has no ipykernel. A paused sandbox is resumed first.
func (s *Sandbox) RunCode(ctx context.Context, code string, in *RunCode, opts *RequestOptions) (*CodeRun, error) {
	var b RunCode
	if in != nil {
		b = *in
	}
	b.Code = code
	return s.c.RunCode(ctx, s.Info.ID, b, opts)
}

// ExecStream Runs a command and yields its output as it is written, stdout and stderr in order; once it ends, wait() returns the process with its exit code.
func (s *Sandbox) ExecStream(cmd string, in *ExecRequest, opts *RequestOptions) *Stream[OutputChunk, Process] {
	c, id := s.c, s.Info.ID
	return newStream(
		func(ctx context.Context) (*Process, error) {
		var b ExecRequest
		if in != nil {
			b = *in
		}
		if cmd != "" {
			b.Cmd = cmd
		}
		b.Wait = Ptr(false)
		return c.Exec(ctx, id, b, opts)
		},
		func(ctx context.Context, t *Process, cursor int64) ([]OutputChunk, int64, *Process, error) {
			a, err := c.ProcessOutput(ctx, id, t.ID, SandboxProcessOutputQuery{Cursor: Ptr(cursor), WaitSeconds: Ptr(float64(8))}, opts)
			if err != nil {
				return nil, 0, nil, err
			}
			return a.Chunks, a.NextCursor, a.Process, nil
		},
		func(t *Process, cursor int64) bool { return t.State != "running" && cursor >= t.OutputBytes },
	)
}
